<script setup>
import {computed} from 'vue'; import {Head,Link,useForm} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; import PageBanner from '../../Components/PageBanner.vue'; defineOptions({layout:AppLayout}); const p=defineProps({vendors:Array,store_url:String,index_url:String}); const f=useForm({vendor_id:'',notes:'',lines:[]}); const v=computed(()=>p.vendors.find(x=>x.id===f.vendor_id)); const select=()=>f.lines=(v.value?.items||[]).filter(x=>Number(x.suggestion)>0).map(x=>({item_id:x.id,quantity:x.suggestion}));
</script>
<template><Head title="Buat Refill"/><div class="units-page"><PageBanner title="Buat Vendor Refill" description="Quantity saran sudah mengurangi stok dan refill terbuka." icon="truck"/><section class="surface-card form-card"><form class="form-card__body form-stack" @submit.prevent="f.post(store_url)"><label>Vendor</label><select v-model="f.vendor_id" class="form-input" required @change="select"><option value="">Pilih Vendor</option><option v-for="x in vendors" :key="x.id" :value="x.id">{{x.code}} · {{x.name}}</option></select><div v-for="row in f.lines" :key="row.item_id" class="form-grid"><span>{{v.items.find(x=>x.id===row.item_id)?.code}} · {{v.items.find(x=>x.id===row.item_id)?.name}}</span><input v-model="row.quantity" class="form-input" type="number" min="0.0001" step="0.0001" required/></div><p v-if="v&&!f.lines.length">Tidak ada barang low stock.</p><textarea v-model="f.notes" class="form-input" placeholder="Catatan (opsional)"/><div class="form-actions"><Link :href="index_url" class="button button--secondary">Batal</Link><button class="button button--primary" :disabled="f.processing||!f.lines.length">Kirim Refill</button></div></form></section></div></template>
